  "carousel": [{"name":"CarouselProps","props":[{"name":"items","type":"CarouselItem[]","required":true,"description":"The slides, left to right."},{"name":"index","type":"number","required":false,"description":"Controlled current slide. Pair with `onIndexChange`. Omit for uncontrolled."},{"name":"defaultIndex","type":"number","required":false,"description":"Initial current slide for the uncontrolled case (read once; default 0)."},{"name":"onIndexChange","type":"(index: number) => void","required":false,"description":"Called with the next current index whenever the slide changes."},{"name":"loop","type":"boolean","required":false,"description":"Wrap from the last slide to the first (and first to last) on arrow nav."},{"name":"showArrows","type":"boolean","required":false,"description":"Show the overlaid prev/next chevron buttons. Default is platform-adaptive: on for web, off for iOS + Android (swipe idioms); pass `true` to opt in."},{"name":"showDots","type":"boolean","required":false,"description":"Show the centered dot indicators below the slides. Default is platform-adaptive: on for web + iOS (UIPageControl), off for Android M3."},{"name":"testID","type":"string","required":false,"description":"E2E hook forwarded to the root element."},{"name":"style","type":"StyleProp<ViewStyle>","required":false,"description":"Outer layout composition only (width/flex within a parent), never a restyle hook."}]}],
