  "sparkline": [{"name":"SparklineProps","props":[{"name":"values","type":"number[]","required":true,"description":"The series to plot; each value becomes one bar, sized against the max."},{"name":"primary","type":"boolean","required":false,"description":"Tone (pick one; default `primary`). Colors the marks."},{"name":"success","type":"boolean","required":false,"description":"Tone (pick one; default `primary`). Colors the marks."},{"name":"destructive","type":"boolean","required":false,"description":"Tone (pick one; default `primary`). Colors the marks."},{"name":"muted","type":"boolean","required":false,"description":"Tone (pick one; default `primary`). Colors the marks."},{"name":"compact","type":"boolean","required":false,"description":"Height (pick one; default medium)."},{"name":"tall","type":"boolean","required":false,"description":"Height (pick one; default medium)."},{"name":"line","type":"boolean","required":false,"description":"A continuous 2px trend line with an area wash and end marker, instead of the bar strip."},{"name":"accessibilityLabel","type":"string","required":false,"description":"Accessible summary (e.g. \"requests, last 11 days\")."},{"name":"testID","type":"string","required":false,"description":"E2E hook forwarded to the root element."},{"name":"style","type":"StyleProp<ViewStyle>","required":false,"description":"For sizing/composition only (e.g. maxWidth); not a styling escape hatch."}]}],
  "spinner": [{"name":"SpinnerProps","props":[{"name":"children","type":"ReactNode","required":false,"description":"Optional label rendered beside (or below) the indicator in the spinner's canonical muted small type. Supplying it turns the bare indicator into a component-owned loading pairing, so the caller never hand-composes a Row/Column + Typography beside a <Spinner />. A bare <Spinner /> (no children) is unchanged."},{"name":"description","type":"ReactNode","required":false,"description":"Optional muted secondary line rendered under the label (a progress hint, an ETA). Stacks under the label inside the control."},{"name":"stacked","type":"boolean","required":false,"description":"Layout axis for the label. Omitted/false: the label sits BESIDE the indicator in a snug row (the inline pairing). `stacked`: the indicator sits over a centered label column (the panel / section-loader form)."},{"name":"small","type":"boolean","required":false,"description":"Size (pick one; default sits between small and large)."},{"name":"large","type":"boolean","required":false,"description":"Size (pick one; default sits between small and large)."},{"name":"primary","type":"boolean","required":false,"description":"Tone (pick one; default is the foreground arc color)."},{"name":"muted","type":"boolean","required":false,"description":"Tone (pick one; default is the foreground arc color)."},{"name":"foreground","type":"boolean","required":false,"description":"Tone (pick one; default is the foreground arc color)."},{"name":"accessibilityLabel","type":"string","required":false,"description":"Accessible description of what is loading. When absent, a string label (children) becomes the accessible name; when neither is present it defaults to \"Loading\"."},{"name":"testID","type":"string","required":false,"description":"E2E hook forwarded to the root element."}]}],
