  "stacked-lists": [{"name":"StackedListProps","props":[{"name":"items","type":"StackedListItem[]","required":false,"description":"Rows to render."},{"name":"title","type":"ReactNode","required":false,"description":"Optional header title; shown above the rows, separated by a rule."},{"name":"action","type":"ReactNode","required":false,"description":"Trailing header content (e.g. an action button); only shown with a title. Takes precedence over `addAction` when both are supplied."},{"name":"addAction","type":"string","required":false,"description":"Convenience header action: renders a small outlined button with a leading plus icon and this label (e.g. \"Add\"). Only shown with a title and when `action` is not set. Serializable, so the playground can drive it."},{"name":"rowMenu","type":"boolean","required":false,"description":"Appends a trailing ghost overflow (\"...\") action-menu button to every row. Press is reported through `onPressItemMenu`."},{"name":"onPressItem","type":"(index: number, event: GestureResponderEvent) => void","required":false,"description":"Press handler for a row, by index. Only used in the `clickable` variant."},{"name":"onPressItemMenu","type":"(index: number, event: GestureResponderEvent) => void","required":false,"description":"Press handler for a row's overflow menu, by index. Used with `rowMenu`."},{"name":"clickable","type":"boolean","required":false,"description":"Variant (pick one; default is the plain two-line list)."},{"name":"card","type":"boolean","required":false,"description":"Variant (pick one; default is the plain two-line list)."},{"name":"flush","type":"boolean","required":false,"description":"Divider modifier: rows are ruled by default; `flush` removes the hairlines."},{"name":"virtualized","type":"boolean","required":false,"description":"Render the rows through a windowed `FlatList` instead of mounting every row up front, for large lists. Give the list a bounded height (via `style`, e.g. `{ maxHeight: 400 }`) so it can scroll; without one it warns and renders eagerly anyway. Default (omitted) mounts all rows, unchanged. Ignored (with a dev warning) when `reorderable` is set: windowing unmounts off-screen rows, which would leave them undraggable and unmeasurable mid-drag."},{"name":"reorderable","type":"boolean","required":false,"description":"Make the rows reorderable: each row gains a leading drag grip (keyboard- and screen-reader-operable: Space grabs, the arrow keys move, Space drops, Escape cancels) and the list becomes one drop zone. The order stays CONTROLLED by the consumer's `items` array: a drop only reports the move through `onReorder`, never reorders internally."},{"name":"onReorder","type":"(move: StackedListMove) => void","required":false,"description":"Fired on drop with the computed move (row id, from/to index, new neighbors)."},{"name":"testID","type":"string","required":false,"description":"E2E hook forwarded to the root element."},{"name":"style","type":"StyleProp<ViewStyle>","required":false,"description":"Outer layout composition only (width/flex within a parent), never a restyle hook."}]}],
  "stats": [{"name":"StatsProps","props":[{"name":"items","type":"StatItem[]","required":true,"description":"The metrics to render, in order."},{"name":"plain","type":"boolean","required":false,"description":"Borderless metric stacks on a shared surface, for nesting inside a card."},{"name":"title","type":"string","required":false,"description":"Optional heading shown above the metrics (mainly for the plain surface)."},{"name":"onPressItem","type":"(index: number) => void","required":false,"description":"Make each metric a tappable target (drill into the underlying detail). When set, every metric renders as a Pressable with a button role and a pressed affordance, so a tappable stat needs no hand-rolled Pressable."},{"name":"testID","type":"string","required":false,"description":"E2E hook forwarded to the root element."},{"name":"style","type":"StyleProp<ViewStyle>","required":false,"description":"Outer layout composition only (width/flex within a parent), never a restyle hook."}]}],
